# Native component procedure catalog. Each source location resolves to a freshly displayed pixel view.
def native_ref(family,cell,side='face'):
 if family=='corporation-sheets':id=f'corp-{side}-{cell}'
 elif family=='emergency-cards':id=f'emergency-{side}-{0 if cell<3 else 3}'
 elif family.startswith('action-deck-'):id='action-'+family.split('-')[-1]+'-four-unique'
 elif family=='asset-cards':id=f'assets-{(cell//3)*3:02}'
 elif family=='investment-cards':id=f'investments-{(cell//4)*4:02}'
 elif family=='event-cards':id=f'events-{side}-{(cell//3)*3:02}'
 elif family=='setup-cards':id=f'setup-{(cell//3)*3:02}'
 elif family=='demand-cards':id=f'demand-{(cell//3)*3:02}'
 elif family=='rival-cards':id=f'rival-{(cell//3)*3:02}'
 n=next(n for n in N if n['id']==id);r=next(r for r in n['rectangles'] if r['cell_zero_based']==cell)
 return {'view_id':id,'atlas':n['source'],'atlas_sha256':n['source_sha256'],'zero_based_cell':cell,'native_rect':r['rect'],'visible_output':n['output'],'visible_sha256':n['output_sha256'],'visible_rect':r['output_rect']}
