 return {'family':family,'name':name,'native_evidence':native_ref(family,cell),'actor':'owning player for assets; winning offer resolver for actions; players collectively for event/setup/demand/rival templates','timing':timing,'activation_or_cost':cost,'target':target,'condition':condition,'ordered_outcome':outcome,'actually_asked_questions':qs,'unasked_residual':residual,'novelty_classification':status}
